<script setup lang="ts">const config = useRuntimeConfig(); const { data, error } = await useFetch<{ data: Array<{ name: string; price: number; category_name?: string; is_available?: boolean }> }>(`${config.public.apiBase}/api/menu-items`); const products = computed(() => data.value?.data || [])</script>
<template><section class="stack"><h1>Our menu</h1><p v-if="error">The menu is unavailable right now.</p><div v-else class="grid"><ProductCard v-for="product in products" :key="product.name" :product="product" /></div><p v-if="!products.length && !error" class="muted">No dishes are available yet.</p></section></template>
